#include <bits/stdc++.h>
using namespace std;
char g[12][12];
bool dfs(int x,int y){
    if(x==9 && y==9) return true;
    if(y==9) return dfs(x+1,0);
    if(g[x][y]!='.') return dfs(x,y+1);
    bool v[12];
    memset(v,false,sizeof(v));
    for(int i=0;i<9;i++){
        if(g[x][i]!='.')v[g[x][i]-'0']=true;
        if(g[i][y]!='.')v[g[i][y]-'0']=true;
    }
    int xx=x/3*3,yy=y/3*3;
    for(int i=xx;i<=xx+2;i++)
        for(int j=yy;j<=yy+2;j++)
            if (g[i][j]!='.')v[g[i][j]-'0']=true;
    for(int i=1;i<=9;i++){
        if(!v[i]){
            g[x][y]=char(i+'0');
            if(dfs(x,y+1)) return true;
            g[x][y]='.';
        }
    }
    return false;    
}
int main()
{
    for(int i=0;i<9;i++) fgets(g[i],12,stdin);
    dfs(0,0);
    for(int i=0;i<9;i++)cout<<g[i];
    return 0;
}
